import assert from "node:assert/strict";
import { wrap, joinFitted } from "../src/fit.js";

test("wrap 在空格处断行", () => {
  assert.deepEqual(wrap("aa bb cc", 5), ["aa bb", "cc"]);
});

test("wrap 不拆长词", () => {
  assert.deepEqual(wrap("aaaaaaa b", 3), ["aaaaaaa", "b"]);
});

