// 把多段文本各自折行后用空行拼接。
// 每段内部按 wrap 规则折行；相邻段之间插入一个空行作为分隔。
// 空段 wrap 返回 []（贡献 0 行），分隔空行照常插入，因此空段被保留为空行。
export function joinFitted(segments, maxWidth) {
  const lines = [];
  segments.forEach((seg, i) => {
    if (i > 0) lines.push(""); // 段间分隔的一个空行
    lines.push(...wrap(seg, maxWidth)); // 空段 wrap 返回 []，自然贡献 0 行
  });
  return lines.join("\n");
}
